package main

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"time"
)

func write(dir, name string) string {
	p := filepath.Join(dir, name)
	_ = os.WriteFile(p, []byte("#!/bin/sh\necho '{\"protocol_version\":1}'\n"), 0o755)
	return p
}

func main() {
	dir, _ := os.MkdirTemp("", "probe")
	defer os.RemoveAll(dir)
	// several distinct, freshly-written scripts
	for i := 0; i < 5; i++ {
		p := write(dir, fmt.Sprintf("entire-agent-p%d", i))
		st := time.Now()
		_, err := exec.CommandContext(context.Background(), p, "info").CombinedOutput()
		fmt.Printf("fresh script %d: %v err=%v\n", i, time.Since(st), err)
	}
	// re-exec the first one
	st := time.Now()
	_, _ = exec.CommandContext(context.Background(), filepath.Join(dir, "entire-agent-p0"), "info").CombinedOutput()
	fmt.Printf("re-exec p0: %v\n", time.Since(st))
	_ = os.Args
}
EOF
go run main.go

